`timescale 1ns / 1ps
// Self-checking testbench for skid_buffer, lanes at WIDTH 8 and WIDTH 1.
module skid_buffer_tb;

    reg        clk = 1'b0;
    reg        rst_n;
    reg        s_valid;
    reg  [7:0] s_data;
    reg        m_ready;

    wire       s_ready8;
    wire       m_valid8;
    wire [7:0] m_data8;
    wire       s_ready1;
    wire       m_valid1;
    wire [0:0] m_data1;
    wire [0:0] s_data1;

    assign s_data1 = s_data[0];

    skid_buffer #(.WIDTH(8)) dut8 (
        .clk     (clk),
        .rst_n   (rst_n),
        .s_valid (s_valid),
        .s_ready (s_ready8),
        .s_data  (s_data),
        .m_valid (m_valid8),
        .m_ready (m_ready),
        .m_data  (m_data8)
    );

    skid_buffer #(.WIDTH(1)) dut1 (
        .clk     (clk),
        .rst_n   (rst_n),
        .s_valid (s_valid),
        .s_ready (s_ready1),
        .s_data  (s_data1),
        .m_valid (m_valid1),
        .m_ready (m_ready),
        .m_data  (m_data1)
    );

    always #5 clk = ~clk;

    // Bookkeeping.
    integer passed = 0;
    integer failed = 0;
    reg     checking = 1'b0;
    reg [8*64-1:0] nonce;
    reg [7:0]  seq = 8'h00;
    reg [31:0] r;
    integer    n_in0;
    integer    n_out0;

    // Reference model: a queue of up to two beats, moved only by port handshakes.
    integer   mcnt   = 0;
    integer   n_in   = 0;
    integer   n_out  = 0;
    integer   n_drop = 0;
    reg [7:0] mq0    = 8'h00;
    reg [7:0] mq1    = 8'h00;
    reg       up;
    reg       dn;

    always @(posedge clk) begin
        if (!rst_n) begin
            n_drop = n_drop + mcnt;
            mcnt   = 0;
        end else begin
            up = s_valid && (mcnt < 2);
            dn = m_ready && (mcnt > 0);
            if (dn) begin
                mq0   = mq1;
                mcnt  = mcnt - 1;
                n_out = n_out + 1;
            end
            if (up) begin
                if (mcnt == 0) mq0 = s_data;
                else           mq1 = s_data;
                mcnt = mcnt + 1;
                n_in = n_in + 1;
            end
        end
    end

    task check;
        input cond;
        input integer id;
        begin
            if (cond) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $error("check %0d failed at time %0t", id, $time);
            end
        end
    endtask

    // Outputs against the model.
    task check_outputs;
        begin
            if (checking) begin
                check(m_valid8 === (mcnt != 0), 100);
                check(s_ready8 === (mcnt < 2), 101);
                check(m_valid1 === (mcnt != 0), 102);
                check(s_ready1 === (mcnt < 2), 103);
                if (mcnt != 0) begin
                    check(m_data8 === mq0, 104);
                    check(m_data1 === mq0[0:0], 105);
                end
            end
        end
    endtask

    // No output may move with m_ready, s_valid or s_data inside a cycle.
    task glitch_check;
        reg [12:0] snap;
        begin
            snap = {s_ready8, m_valid8, m_data8, s_ready1, m_valid1, m_data1};
            m_ready = ~m_ready;
            s_valid = ~s_valid;
            s_data  = ~s_data;
            #1;
            if (checking)
                check(snap === {s_ready8, m_valid8, m_data8, s_ready1, m_valid1, m_data1}, 110);
            m_ready = ~m_ready;
            s_valid = ~s_valid;
            s_data  = ~s_data;
            #1;
        end
    endtask

    // One clock cycle, entered and left just after a falling edge.
    task step;
        input sv_i;
        input mr_i;
        reg       acc;
        reg       stalled;
        reg [7:0] pd;
        begin
            r   = $random;
            acc = sv_i && (mcnt < 2) && rst_n;
            s_valid = sv_i;
            m_ready = mr_i;
            if (sv_i && !acc) s_data = r[7:0];   // not accepted: any data
            else              s_data = seq;
            #1;
            check_outputs;
            glitch_check;
            stalled = m_valid8 && !m_ready && rst_n;
            pd      = m_data8;
            @(posedge clk);
            @(negedge clk);
            if (acc) seq = seq + 8'd1;
            if (checking && stalled)
                check((m_valid8 === 1'b1) && (m_data8 === pd), 111);
        end
    endtask

    task drain;
        begin
            repeat (3) step(1'b0, 1'b1);
            check((mcnt == 0) && (m_valid8 === 1'b0) && (m_valid1 === 1'b0) &&
                  (s_ready8 === 1'b1) && (s_ready1 === 1'b1), 50);
        end
    endtask

    task random_phase;
        input [3:0] pv;
        input [3:0] pr;
        input integer n;
        integer   k;
        reg [31:0] rr;
        begin
            for (k = 0; k < n; k = k + 1) begin
                rr = $random;
                step(rr[3:0] < pv, rr[7:4] < pr);
            end
        end
    endtask

    initial begin
        nonce = {64{8'h00}};
        if ($value$plusargs("nirmaan_nonce=%s", nonce) == 0) nonce = {64{8'h00}};

        rst_n   = 1'b0;
        s_valid = 1'b0;
        m_ready = 1'b0;
        s_data  = 8'h00;
        @(posedge clk);
        @(negedge clk);
        checking = 1'b1;

        // Reset values, with traffic offered during reset.
        step(1'b1, 1'b1);
        step(1'b1, 1'b0);
        check((m_valid8 === 1'b0) && (s_ready8 === 1'b1) &&
              (m_valid1 === 1'b0) && (s_ready1 === 1'b1), 1);
        rst_n = 1'b1;
        step(1'b0, 1'b1);
        step(1'b0, 1'b0);
        check((m_valid8 === 1'b0) && (s_ready8 === 1'b1), 2);

        // One-cycle latency.
        step(1'b1, 1'b1);
        check((m_valid8 === 1'b1) && (m_data8 === (seq - 8'd1)) && (m_valid1 === 1'b1), 10);
        step(1'b0, 1'b1);
        check((m_valid8 === 1'b0) && (m_valid1 === 1'b0), 11);

        // Full throughput: one in and one out on every edge after the first.
        n_in0  = n_in;
        n_out0 = n_out;
        repeat (40) step(1'b1, 1'b1);
        check((n_in - n_in0) == 40, 30);
        check((n_out - n_out0) == 39, 31);
        drain;

        // Stall with one beat held: a second is accepted.
        step(1'b1, 1'b0);
        check((m_valid8 === 1'b1) && (s_ready8 === 1'b1) && (s_ready1 === 1'b1), 20);
        step(1'b1, 1'b0);
        check((s_ready8 === 1'b0) && (s_ready1 === 1'b0) && (m_valid8 === 1'b1), 21);
        // Two held: a third is not accepted.
        n_in0 = n_in;
        step(1'b1, 1'b0);
        step(1'b1, 1'b0);
        step(1'b1, 1'b0);
        check((n_in == n_in0) && (s_ready8 === 1'b0), 22);
        // Ready rises: beats leave in order, s_ready rises after one leaves.
        n_out0 = n_out;
        step(1'b1, 1'b1);
        check((s_ready8 === 1'b1) && (m_valid8 === 1'b1) &&
              ((n_out - n_out0) == 1) && (n_in == n_in0), 23);
        step(1'b0, 1'b1);
        step(1'b0, 1'b1);
        check(((n_out - n_out0) == 2) && (m_valid8 === 1'b0), 24);
        drain;

        // Ready low for one cycle, then for several, with a continuous sender.
        step(1'b1, 1'b1);
        step(1'b1, 1'b0);
        step(1'b1, 1'b1);
        step(1'b1, 1'b1);
        step(1'b1, 1'b0);
        step(1'b1, 1'b0);
        step(1'b1, 1'b0);
        step(1'b1, 1'b1);
        step(1'b1, 1'b1);
        step(1'b1, 1'b1);
        drain;

        // Random traffic against the model, ending in a drain.
        random_phase(4'd8,  4'd8,  500);
        random_phase(4'd14, 4'd4,  500);
        random_phase(4'd4,  4'd14, 500);
        random_phase(4'd12, 4'd12, 500);
        drain;

        // Reset with two beats held.
        step(1'b1, 1'b0);
        step(1'b1, 1'b0);
        check((s_ready8 === 1'b0) && (m_valid8 === 1'b1) && (s_ready1 === 1'b0), 40);
        rst_n = 1'b0;
        step(1'b1, 1'b1);
        rst_n = 1'b1;
        check((m_valid8 === 1'b0) && (s_ready8 === 1'b1) &&
              (m_valid1 === 1'b0) && (s_ready1 === 1'b1), 41);
        repeat (6) step(1'b1, 1'b1);
        drain;

        // Scoreboard: every accepted beat left once or was dropped by reset.
        check_outputs;
        check(n_in == (n_out + n_drop), 90);
        check(mcnt == 0, 91);

        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule
=== END FILE ===
